import { readFileSync } from "fs";

const [s, t] = readFileSync(0, "utf8").trim().split("\n");
const n = s.length;
const m = t.length;

// dp[i][j] = S の先頭 i 文字と T の先頭 j 文字の LCS の長さ。2 行だけ持つ
let prev = new Int32Array(m + 1);
let cur = new Int32Array(m + 1);
for (let i = 1; i <= n; i++) {
  for (let j = 1; j <= m; j++) {
    if (s[i - 1] === t[j - 1]) cur[j] = prev[j - 1] + 1;
    else cur[j] = Math.max(prev[j], cur[j - 1]);
  }
  [prev, cur] = [cur, prev];
}
